use std::fs;
use ulw_loop_core::command_types::{AddGoalOptions, CreateGoalsOptions, RecordEvidenceOptions};
use ulw_loop_core::paths::UlwLoopScope;
use ulw_loop_core::plan_io::read_ulw_loop_plan;
use ulw_loop_core::sdk::{ulw_loop_manifest, AgentToolkit, ToolkitContext, ToolkitResponse, ULW_LOOP_OPERATIONS};
use ulw_loop_core::success_criteria_input::SuccessCriterionInput;
use ulw_loop_core::surface::UlwLoopToolkitSurface;

fn fixture(surface: UlwLoopToolkitSurface, session: &str) -> (tempfile::TempDir, AgentToolkit) { let dir = tempfile::tempdir().expect("tempdir"); let tk = AgentToolkit::new(ToolkitContext { cwd: dir.path().display().to_string(), session_id: session.into(), surface }, None).expect("context"); assert!(matches!(tk.create_goals(&CreateGoalsOptions { brief: "- alpha goal\n- beta goal".into(), goals: None, codex_goal_mode: None, force: None, validation_batches_json: None }), ToolkitResponse::Success { .. })); (dir, tk) }

#[test]
fn manifest_operations_are_self_describing() { let methods = ["help","createGoals","status","completeGoals","checkpoint","steer","addGoal","criteria","recordEvidence","recordReviewBlockers"]; let manifest = ulw_loop_manifest(); assert_eq!(manifest.operations.len(), ULW_LOOP_OPERATIONS.len()); for (op, method) in manifest.operations.iter().zip(methods) { assert_eq!(op.method, method); assert!(op.description.len() > 20); } let record = manifest.operations.iter().find(|o| o.name == "record-evidence").unwrap(); for key in ["goalId","criterionId","evidence","status","notes","artifacts"] { assert!(record.args.contains_key(key)); } }
#[test]
fn help_returns_manifest() { let (_dir, tk) = fixture(UlwLoopToolkitSurface::OmoSenpi, "dx-help"); match tk.help() { ToolkitResponse::Success { result, .. } => assert!(result.operations.iter().any(|o| o.method == "recordEvidence")), _ => panic!("help failed") } }
#[test]
fn add_goal_persists_explicit_sequential_criteria() { let (dir, tk) = fixture(UlwLoopToolkitSurface::OmoSenpi, "dx-add-criteria"); let added = tk.add_goal(&AddGoalOptions { title: "lane".into(), objective: "ship the lane".into(), evidence: None, success_criteria: Some(vec![SuccessCriterionInput { scenario: "curl -i /health returns 200".into(), expected_evidence: "status line captured in health.log".into(), user_model: None, essential: None }, SuccessCriterionInput { scenario: "malformed body returns 400".into(), expected_evidence: "curl transcript".into(), user_model: Some("edge".into()), essential: Some(false) }]) }); match added { ToolkitResponse::Success { result, .. } => { assert_eq!(result.goal.success_criteria[0].id, "C001"); assert_eq!(result.goal.success_criteria[1].id, "C002"); assert_eq!(result.goal.success_criteria[0].user_model, "happy"); assert_eq!(result.goal.success_criteria[1].essential, Some(false)); assert_eq!(read_ulw_loop_plan(dir.path(), Some(&UlwLoopScope { session_id: Some("dx-add-criteria".into()), ..Default::default() })).unwrap().goals.last().unwrap().success_criteria.len(), 2); }, _ => panic!("add failed") } }
#[test]
fn invalid_success_criteria_fail_closed() { let (_dir, tk) = fixture(UlwLoopToolkitSurface::OmoSenpi, "dx-add-invalid"); for criteria in [vec![], vec![SuccessCriterionInput { scenario: "  ".into(), expected_evidence: "x".into(), user_model: None, essential: None }], vec![SuccessCriterionInput { scenario: "s".into(), expected_evidence: "".into(), user_model: None, essential: None }]] { match tk.add_goal(&AddGoalOptions { title: "lane".into(), objective: "ship".into(), evidence: None, success_criteria: Some(criteria) }) { ToolkitResponse::Failure { error, .. } => assert_eq!(error.code, "ULW_LOOP_ARGUMENT_INVALID"), _ => panic!("invalid criteria accepted") } } }
#[test]
fn missing_success_criteria_use_surface_placeholders() { let (_dir, tk) = fixture(UlwLoopToolkitSurface::OmoSenpi, "dx-add-placeholder"); match tk.add_goal(&AddGoalOptions { title: "lane".into(), objective: "ship".into(), evidence: None, success_criteria: None }) { ToolkitResponse::Success { result, .. } => { let evidence = result.goal.success_criteria[0].expected_evidence.clone(); assert!(evidence.contains("successCriteria")); }, _ => panic!("add failed") } }
#[test]
fn evidence_records_existing_artifacts() { let (dir, tk) = fixture(UlwLoopToolkitSurface::OmoSenpi, "dx-artifacts"); fs::create_dir_all(dir.path().join("evidence")).unwrap(); fs::write(dir.path().join("evidence/gate.log"), "exit 0\n").unwrap(); let goal = match tk.complete_goals(None) { ToolkitResponse::Success { result: ulw_loop_core::plan_crud::StartNextResult::Started { goal, .. }, .. } => goal, _ => panic!() }; let result = tk.record_evidence(&RecordEvidenceOptions { goal_id: goal.id, criterion_id: "C001".into(), status: "pass".into(), evidence: "gate green".into(), notes: None, artifacts: Some(vec!["evidence/gate.log".into()]) }); match result { ToolkitResponse::Success { result, .. } => assert_eq!(result.criterion.artifacts.unwrap(), vec!["evidence/gate.log"]), _ => panic!("evidence failed") } }
#[test]
fn missing_artifact_fails_without_recording() { let (dir, tk) = fixture(UlwLoopToolkitSurface::OmoSenpi, "dx-artifact-missing"); let goal = match tk.complete_goals(None) { ToolkitResponse::Success { result: ulw_loop_core::plan_crud::StartNextResult::Started { goal, .. }, .. } => goal, _ => panic!() }; match tk.record_evidence(&RecordEvidenceOptions { goal_id: goal.id, criterion_id: "C001".into(), status: "pass".into(), evidence: "gate green".into(), notes: None, artifacts: Some(vec!["evidence/does-not-exist.log".into()]) }) { ToolkitResponse::Failure { error, .. } => assert_eq!(error.code, "ULW_LOOP_EVIDENCE_ARTIFACT_MISSING"), _ => panic!("missing artifact accepted") } let plan = read_ulw_loop_plan(dir.path(), Some(&UlwLoopScope { session_id: Some("dx-artifact-missing".into()), ..Default::default() })).unwrap(); assert_eq!(plan.goals[0].success_criteria[0].status, "pending"); }
#[test]
fn status_exposes_stable_evidence_root() { let (dir, tk) = fixture(UlwLoopToolkitSurface::OmoSenpi, "dx-evidence-root"); match tk.status() { ToolkitResponse::Success { result, .. } => assert_eq!(result.evidence_root, ".omo/evidence/ulw/dx-evidence-root"), _ => panic!() }; assert!(matches!(tk.complete_goals(None), ToolkitResponse::Success { .. })); match tk.status() { ToolkitResponse::Success { result, .. } => { assert_eq!(result.evidence_root, ".omo/evidence/ulw/dx-evidence-root"); assert!(result.current_attempt_dir.unwrap().contains("G001-alpha-goal/a")); }, _ => panic!("status failed") }; let _ = dir; }
